WITH root_topics(id, name) AS (
    VALUES
        ('00000000-0000-4000-8000-000000000001', 'Алгоритмы'),
        ('00000000-0000-4000-8000-000000000002', 'Структуры данных'),
        ('00000000-0000-4000-8000-000000000003', 'Математика'),
        ('00000000-0000-4000-8000-000000000004', 'Графы'),
        ('00000000-0000-4000-8000-000000000005', 'Строки'),
        ('00000000-0000-4000-8000-000000000006', 'Основы программирования'),
        ('00000000-0000-4000-8000-000000000007', 'Объектно-ориентированное программирование')
)
INSERT INTO topic (id, name, parent_id)
SELECT id::uuid, name, NULL::uuid
FROM root_topics
ON CONFLICT (id) DO UPDATE
SET name = EXCLUDED.name,
    parent_id = EXCLUDED.parent_id;

